// ==========================================
// 3. شاشة البداية
// ==========================================

const beginBtn = document.getElementById("beginBtn");
const cover = document.getElementById("cover");
const experience = document.getElementById("experience");
const flowerRain = document.getElementById("flowerRain");

beginBtn.addEventListener("click", () => {

  cover.classList.add("leaving");

  cover.style.transition = "opacity .9s ease, transform .9s ease";
  cover.style.opacity = "0";
  cover.style.transform = "scale(1.04)";

  // إخفاء الورد
  if (flowerRain) {
    flowerRain.style.transition = "opacity .8s ease";
    flowerRain.style.opacity = "0";
  }

  setTimeout(() => {

    cover.remove();

    if (flowerRain) {
      flowerRain.remove();
    }

    experience.classList.remove("hidden");

    experience.scrollIntoView({
      behavior: "smooth"
    });

  }, 900);

});


// ==========================================
// 4. الورد المتساقط في شاشة البداية
// ==========================================

const flowers = ["🌹", "🌷", "🌸", "💮", "🌺", "💐"];

if (flowerRain) {

  for (let i = 0; i < 60; i++) {

    const flower = document.createElement("span");

    flower.classList.add("flower");

    flower.textContent =
      flowers[Math.floor(Math.random() * flowers.length)];

    flower.style.setProperty(
      "--left",
      Math.random() * 100 + "%"
    );

    flower.style.setProperty(
      "--size",
      (18 + Math.random() * 25) + "px"
    );

    flower.style.setProperty(
      "--duration",
      (7 + Math.random() * 9) + "s"
    );

    flower.style.setProperty(
      "--delay",
      (-Math.random() * 15) + "s"
    );

    flower.style.setProperty(
      "--drift",
      (Math.random() * 140 - 70) + "px"
    );

    flowerRain.appendChild(flower);

  }

}


