// ==========================================
// 6. ظهور الصور بالتتابع أثناء التمرير
// ==========================================

const memoryCards = document.querySelectorAll(".memory-card");

if ("IntersectionObserver" in window) {

  const observer = new IntersectionObserver((entries, currentObserver) => {

    entries.forEach((entry) => {

      if (entry.isIntersecting) {

        const card = entry.target;

        // تأخير بسيط لظهور الصور
        const delay = Number(card.dataset.delay || 0);

        setTimeout(() => {
          card.classList.add("show");
        }, delay);

        // وقف مراقبة الصورة بعد ظهورها
        currentObserver.unobserve(card);

      }

    });

  }, {
    threshold: 0.15
  });

  memoryCards.forEach((card, index) => {

    card.dataset.delay = (index % 2) * 180;

    observer.observe(card);

  });

} else {

  // بديل للمتصفحات القديمة
  memoryCards.forEach((card) => {
    card.classList.add("show");
  });

}


// ==========================================
// 7. صندوق الهدايا
// ==========================================

const giftBox = document.getElementById("giftBox");
const surprises = document.getElementById("surprises");
const giftHint = document.getElementById("giftHint");
const restartBtn = document.getElementById("backToTop");


// إطلاق الفراشات والقلوب
function releaseButterflies() {

  const symbols = ["🦋", "💗", "✨", "🌸", "💕"];

  const rect = giftBox.getBoundingClientRect();

  for (let i = 0; i < 24; i++) {

    const butterfly = document.createElement("span");

    butterfly.className = "butterfly";

    butterfly.textContent =
      symbols[i % symbols.length];

    butterfly.style.left =
      `${rect.left + rect.width / 2}px`;

    butterfly.style.top =
      `${rect.top + 45}px`;

    butterfly.style.setProperty(
      "--dx",
      `${(Math.random() - 0.5) * 560}px`
    );

    butterfly.style.setProperty(
      "--dy",
      `${-100 - Math.random() * 420}px`
    );

    butterfly.style.setProperty(
      "--rot",
      `${(Math.random() - 0.5) * 100}deg`
    );

    document.body.appendChild(butterfly);

    butterfly.addEventListener("animationend", () => {
      butterfly.remove();
    }, { once: true });

  }

}


// فتح الصندوق
function openGift() {

  if (giftBox.classList.contains("open")) {
    return;
  }

  giftBox.classList.add("open");

  surprises.classList.add("show");

  giftHint.textContent =
    `كل الهدايا دي ليكي يا ${HER_NAME} 💖`;

  restartBtn.classList.add("show");

  releaseButterflies();

}

giftBox.addEventListener("click", openGift);


// ==========================================
// 8. زر الرجوع لأعلى
// ==========================================

window.addEventListener("scroll", () => {

  if (window.scrollY > 400) {

    restartBtn.classList.add("show");

  } else {

    restartBtn.classList.remove("show");

  }

});

restartBtn.addEventListener("click", () => {

  window.scrollTo({
    top: 0,
    behavior: "smooth"
  });

});
// ==========================================
// 9. فتح الصور مع مؤثرات النيون والفراشات
// ==========================================

const photoLightbox = document.getElementById("photoLightbox");
const lightboxImage = document.getElementById("lightboxImage");
const lightboxClose = document.getElementById("lightboxClose");
const lightboxEffects = document.getElementById("lightboxEffects");

const photoCards = document.querySelectorAll(".memory-card");

const particleSymbols = [
  "🦋", "🌹", "🌸", "🌷", "💗",
  "💕", "✨", "💖", "🌺", "💮"
];


// إنشاء انفجار الورود والفراشات
function createPhotoEffects() {

  // تنظيف المؤثرات القديمة
  lightboxEffects.replaceChildren();

  // إنشاء 55 عنصرًا في كل مرة
  for (let i = 0; i < 55; i++) {

    const particle = document.createElement("span");

    particle.className = "photo-particle";

    particle.textContent =
      particleSymbols[
        Math.floor(Math.random() * particleSymbols.length)
      ];

    particle.style.setProperty(
      "--particle-x",
      `${(Math.random() - 0.5) * window.innerWidth * 1.3}px`
    );

    particle.style.setProperty(
      "--particle-y",
      `${(Math.random() - 0.5) * window.innerHeight * 1.3}px`
    );

    particle.style.setProperty(
      "--particle-size",
      `${20 + Math.random() * 25}px`
    );

    particle.style.setProperty(
      "--particle-duration",
      `${2.5 + Math.random() * 2}s`
    );

    particle.style.setProperty(
      "--particle-delay",
      `${Math.random() * 0.5}s`
    );

    particle.style.setProperty(
      "--particle-rotation",
      `${Math.random() * 720 - 360}deg`
    );

    lightboxEffects.appendChild(particle);

    particle.addEventListener("animationend", () => {
      particle.remove();
    }, { once: true });

  }

}


// فتح الصورة
function openPhoto(image) {

  lightboxImage.src = image.src;
  lightboxImage.alt = image.alt;

  photoLightbox.classList.add("active");
  photoLightbox.setAttribute("aria-hidden", "false");

  document.body.style.overflow = "hidden";

  createPhotoEffects();

}


// إغلاق الصورة
function closePhoto() {

  photoLightbox.classList.remove("active");
  photoLightbox.setAttribute("aria-hidden", "true");

  document.body.style.overflow = "";

  lightboxEffects.replaceChildren();

  // إفراغ الصورة بعد انتهاء الإغلاق
  setTimeout(() => {

    if (!photoLightbox.classList.contains("active")) {
      lightboxImage.src = "";
    }

  }, 400);

}


// الضغط على أي صورة
photoCards.forEach((card) => {

  const image = card.querySelector("img");

  if (!image) return;

  image.addEventListener("click", () => {
    openPhoto(image);
  });

});


// زر X
lightboxClose.addEventListener("click", closePhoto);


// الضغط خارج الصورة
photoLightbox.addEventListener("click", (event) => {

  if (
    event.target === photoLightbox ||
    event.target === lightboxEffects
  ) {
    closePhoto();
  }

});


// الإغلاق بزر Escape
document.addEventListener("keydown", (event) => {

  if (
    event.key === "Escape" &&
    photoLightbox.classList.contains("active")
  ) {
    closePhoto();
  }

});


const music = document.getElementById("backgroundMusic");
const musicBtn = document.getElementById("musicBtn");
const musicPlayer = document.getElementById("musicPlayer");
const musicLabel = document.getElementById("musicLabel");

musicBtn.addEventListener("click", () => {

  if (music.paused) {

    music.play().then(() => {
      musicPlayer.classList.add("playing");
      musicLabel.textContent = "أغنيتنا شغالة ❤️";
      musicBtn.setAttribute("aria-label", "إيقاف الموسيقى");
    }).catch((error) => {
      console.log("تعذر تشغيل الأغنية:", error);
    });

  } else {

    music.pause();

    musicPlayer.classList.remove("playing");
    musicLabel.textContent = "شغّلي أغنيتنا ❤️";
    musicBtn.setAttribute("aria-label", "تشغيل الموسيقى");

  }

});